def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    for comp in components(g == 0):
        s = set(comp)
        ring = set()
        for y, x in comp:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W and (ny, nx) not in s:
                    ring.add((ny, nx))
        n1 = sum(1 for p in ring if g[p] == 1)
        n2 = sum(1 for p in ring if g[p] == 2)
        col = 1 if n1 >= n2 else 2
        for p in comp:
            out[p] = col
        emit(out, f"Room {bbox(comp)} has {n1} ones and {n2} twos on its walls; fill it with {col}.")
    emit(out, "All rooms filled with their wall-majority marker colour.")
    return out
